378	    /** A sheet's descendants: the sheets naming it as their parent, their children and so on, nearer first,
379	     *  each once and never the sheet itself. */
380	    public List<String> descendants(String sheetId) {
381	        List<String> found = new java.util.ArrayList<>();
382	        java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(sheetId));
383	        while (!pending.isEmpty()) {
384	            for (String child : jdbc.queryForList("SELECT id FROM sheet WHERE parent_id = ? ORDER BY id", String.class, pending.poll())) {
385	                if (child.equals(sheetId) || found.contains(child)) continue;
386	                found.add(child);
387	                pending.add(child);
388	            }
389	        }
390	        return found;
391	    }
