398	        java.util.Set<String> sources = new java.util.HashSet<>();
399	        for (String at = sheetId; at != null && sources.add(at); at = clonedFrom(at)) {
400	            if (!at.equals(sheetId) && !found.contains(at)) found.add(at);
401	            List<String> up = lineage(at);
402	            for (String a : up.size() > 3 ? up.subList(0, 3) : up) {
403	                if (!a.equals(sheetId) && !found.contains(a)) found.add(a);
404	            }
405	        }
406	        return found;
