644	    public static LocalDate businessDaysAfter(java.util.Set<String> holidays, LocalDate date, int terms) {
645	        int counted = 0;
646	        while (counted < terms) {
647	            date = date.plusDays(1);
648	            java.time.DayOfWeek day = date.getDayOfWeek();
649	            if (day != java.time.DayOfWeek.SATURDAY && day != java.time.DayOfWeek.SUNDAY
650	                    && !holidays.contains(date.toString())) {
651	                counted++;
652	            }
653	        }
654	        return date;
655	    }
