669	        jdbc.query("SELECT action, roles FROM sheet_permission WHERE sheet_id = ?",
670	                (org.springframework.jdbc.core.RowCallbackHandler) rs -> perms.put(rs.getString("action"), rs.getString("roles")),
671	                sheetId);
672	        Map<String, String> ordered = new LinkedHashMap<>();
673	        for (String action : PERMISSION_ACTIONS) {
