681	        if (roles == null || roles.isEmpty()) {
682	            jdbc.update("DELETE FROM sheet_permission WHERE sheet_id = ? AND action = ?", sheetId, action);
683	        } else {
684	            jdbc.update("MERGE INTO sheet_permission (sheet_id, action, roles) KEY (sheet_id, action) VALUES (?, ?, ?)",
685	                    sheetId, action, roles);
686	        }
687	    }
