689	    /** Whether a user may take an action on the sheet: by the sheet's permission matrix entry for it, else the
690	     *  standing rule (open, settle, void and close by clerk and steward; reassign and reopen by steward; today by
691	     *  anyone but a viewer). */
692	    public boolean allows(String sheetId, String action, String user) {
693	        List<String> found = jdbc.query("SELECT roles FROM sheet_permission WHERE sheet_id = ? AND action = ?",
694	                (rs, i) -> rs.getString("roles"), sheetId, action);
695	        List<String> roles = found.isEmpty()
696	                ? (action.equals("reassign") || action.equals("reopen") ? List.of(STEWARD)
697	                        : action.equals("today") ? List.of(CLERK, STEWARD, RESTRICTED) : List.of(CLERK, STEWARD))
698	                : List.of(found.get(0).split(","));
699	        return roles.contains(role(sheetId, user));
700	    }
701	
702	    /** A limit as shown: two decimals, a dot, no grouping. */
703	    public static String money(BigDecimal v) {
704	        return v.setScale(2).toPlainString();
705	    }
706	}
